import { describe, expect, test } from "bun:test";
import { relayCanReach } from "../src/index.ts";

// Generated by CPython 3.13.4 as `ipaddress.ip_address(host).is_global`, ValueError read as
// false: every special-purpose range's edges, IPv4-mapped/compatible/NAT64/6to4 spellings, zone
// ids, malformed text, and seeded fuzz around all of them.
const golden = (await Bun.file(`${import.meta.dir}/fixtures/is-global.json`).json()) as {
  python: string;
  cases: [string, boolean][];
};

const SPEC_TABLE: readonly (readonly [string, boolean])[] = [
  ["8.8.8.8", true],
  ["1.1.1.1", true],
  ["104.16.0.1", true],
  ["10.0.0.1", false],
  ["172.16.5.4", false],
  ["172.31.255.255", false],
  ["172.32.0.1", true],
  ["192.168.1.20", false],
  ["100.64.0.1", false],
  ["100.101.102.103", false],
  ["100.127.255.255", false],
  ["100.128.0.1", true],
  ["169.254.1.1", false],
  ["127.0.0.1", false],
  ["0.0.0.0", false],
  ["0.1.2.3", false],
  ["192.0.0.1", false],
  ["192.0.0.9", true],
  ["192.0.0.10", true],
  ["192.0.0.170", false],
  ["192.0.0.171", false],
  ["192.0.2.1", false],
  ["198.18.0.1", false],
  ["198.19.255.255", false],
  ["198.51.100.1", false],
  ["203.0.113.9", false],
  ["224.0.0.1", true],
  ["239.255.255.250", true],
  ["240.0.0.1", false],
  ["255.255.255.255", false],
  ["255.255.255.254", false],
  ["abcd1234-5678-90ab-cdef-1234567890ab.local", false],
  ["localhost", false],
  ["", false],
  ["010.1.1.1", false],
  ["1.2.3", false],
  ["1.1.1.1.", false],
  ["1.1.1.256", false],
  ["2606:4700:4700::1111", true],
  ["2001:4860:4860::8888", true],
  ["::1", false],
  ["::", false],
  ["fe80::1", false],
  ["fe80::1%en0", false],
  ["FE80::1", false],
  ["fd7a:115c:a1e0::1", false],
  ["fc00::1", false],
  ["::ffff:192.168.1.1", false],
  ["::ffff:c0a8:101", false],
  ["::ffff:8.8.8.8", true],
  ["::ffff:0808:0808", true],
  ["::ffff:100.64.0.1", false],
  ["::192.168.1.1", true],
  ["64:ff9b::808:808", true],
  ["64:ff9b::192.168.1.1", true],
  ["64:ff9b:1::1", false],
  ["100::1", false],
  ["2001::1", false],
  ["2001:1::1", true],
  ["2001:2::1", false],
  ["2001:3::1", true],
  ["2001:4:112::1", true],
  ["2001:20::1", true],
  ["2001:30::1", true],
  ["2001:db8::1", false],
  ["2001:db8::1%1", false],
  ["2002::1", false],
  ["3fff::1", false],
  ["ff02::1", true],
  ["fec0::1", true],
  ["2606:4700:4700::1111%eth0", true],
  ["2606:4700::ABCD", true],
  ["[::1]", false],
  ["fe80::1%", false],
  ["0x1.1.1.1", false],
  ["::ffff:256.1.1.1", false],
];

describe("relayCanReach", () => {
  test("the spec's truth table", () => {
    expect(SPEC_TABLE).toHaveLength(76);
    const got = SPEC_TABLE.map(([host]) => [host, relayCanReach(host)]);
    expect(got).toEqual(SPEC_TABLE.map(([host, expected]) => [host, expected]));
  });

  test("CPython's golden table", () => {
    expect(golden.python).toBe("3.13.4");
    expect(golden.cases.length).toBeGreaterThan(6000);
    const mismatches = golden.cases.filter(([host, expected]) => relayCanReach(host) !== expected);
    expect(mismatches).toEqual([]);
  });

  test("zone ids are ignored, but an empty or doubled one is malformed", () => {
    expect(relayCanReach("2606:4700::1%a b")).toBe(true);
    expect(relayCanReach("::ffff:8.8.8.8%7")).toBe(true);
    expect(relayCanReach("2606:4700::1%%")).toBe(false);
    expect(relayCanReach("2606:4700::1%a%b")).toBe(false);
    expect(relayCanReach("2606:4700::1%a/b")).toBe(false);
  });

  test("compressed forms at both ends and an embedded IPv4 tail", () => {
    expect(relayCanReach("2606:4700:4700:1:2:3:4::")).toBe(true);
    expect(relayCanReach("::2606:4700:4700:1:2:3:4")).toBe(true);
    expect(relayCanReach("2606:4700:4700::1:2:3:4")).toBe(true);
    expect(relayCanReach("2606:4700:4700:1:2:3::4:5")).toBe(false);
    expect(relayCanReach("2606:4700:1:2:3:4:8.8.8.8")).toBe(true);
    expect(relayCanReach("2606:4700:1:2:3:4:5:8.8.8.8")).toBe(false);
    expect(relayCanReach("::ffff:0:8.8.8.8")).toBe(true);
  });
});
